```php
function keluarkan(array $data, string $rahsia): string {
    $h = rtrim(strtr(base64_encode(json_encode(['alg' => 'HS256'])), '+/', '-_'), '=');
    $b = rtrim(strtr(base64_encode(json_encode($data + ['exp' => time() + 900])), '+/', '-_'), '=');
    $s = rtrim(strtr(base64_encode(hash_hmac('sha256', "$h.$b", $rahsia, true)), '+/', '-_'), '=');
    return "$h.$b.$s";
}
function sahkan(string $token, string $rahsia): ?array {
    $bah = explode('.', $token);
    if (count($bah) !== 3) return null;
    [$h, $b, $s] = $bah;
    $jangka = rtrim(strtr(base64_encode(hash_hmac('sha256', "$h.$b", $rahsia, true)), '+/', '-_'), '=');
    if (! hash_equals($jangka, (string) $s)) return null;
    $data = json_decode(base64_decode(strtr($b, '-_', '+/')), true);
    return ($data['exp'] ?? 0) > time() ? $data : null;
}
```
HMAC-SHA256 + base64url + `hash_equals` (selamat-masa!) + tamat 15 minit. Tulis sekali untuk faham; guna pustaka (`firebase/php-jwt`) untuk prod.

